package org.efootballrevival.runtimeprobe;
import android.app.Activity;import android.graphics.*;import android.graphics.drawable.*;import android.content.res.ColorStateList;import android.view.*;import android.widget.*;import java.util.Random;
public final class EarthTheme {
 private static Bitmap earth;
 private static synchronized Bitmap globe(){if(earth!=null)return earth;int n=384;Bitmap b=Bitmap.createBitmap(n,n,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Paint p=new Paint(3);float r=n*.43f,x=n*.5f,y=x;
  p.setShader(new RadialGradient(x,y,r*1.17f,new int[]{0x00000000,0x003edaff,0x603edaff,0x003edaff},new float[]{0,.78f,.88f,1},Shader.TileMode.CLAMP));c.drawCircle(x,y,r*1.17f,p);p.setShader(null);Path clip=new Path();clip.addCircle(x,y,r,Path.Direction.CW);c.save();c.clipPath(clip);p.setShader(new RadialGradient(x-r*.4f,y-r*.4f,r*1.8f,new int[]{0xff287fb1,0xff10517e,0xff06172d},new float[]{0,.58f,1},Shader.TileMode.CLAMP));c.drawCircle(x,y,r,p);p.setShader(null);p.setColor(0xff51a7a1);
  double[][][] land={{{-99,60},{-65,56},{-48,38},{-70,23},{-88,17},{-101,31},{-113,39}},{{-78,13},{-48,4},{-38,-13},{-52,-25},{-66,-53},{-74,-34},{-79,-8}},{{-15,35},{12,38},{35,29},{45,8},{30,-12},{23,-34},{10,-25},{4,-3},{-13,7}},{{-9,40},{6,54},{24,63},{49,57},{61,42},{39,27},{20,37}},{{44,12},{52,27},{71,23},{80,8},{65,-1}},{{-48,59},{-30,69},{-40,80},{-57,75}},{{110,-12},{147,-15},{153,-34},{132,-39},{115,-27}}};
  for(double[][] poly:land){double facing=0;for(double[] xy:poly)facing+=Math.cos(Math.toRadians(xy[0]+15));if(facing<0)continue;Path shape=new Path();for(int i=0;i<poly.length;i++){double lon=Math.toRadians(poly[i][0]+15),lat=Math.toRadians(poly[i][1]);float xx=x+(float)(Math.cos(lat)*Math.sin(lon))*r,yy=y-(float)Math.sin(lat)*r;if(i==0)shape.moveTo(xx,yy);else shape.lineTo(xx,yy);}shape.close();c.drawPath(shape,p);}
  p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setColor(0x163bdad3);for(int k=-2;k<=2;k++){float dy=r*k/3f,rx=(float)Math.sqrt(r*r-dy*dy);c.drawOval(new RectF(x-rx,y+dy-r*.08f,x+rx,y+dy+r*.08f),p);}p.setStyle(Paint.Style.FILL);p.setShader(new LinearGradient(x-r,y,x+r,y,new int[]{0x00020d22,0x09020d22,0xd9050b1c},new float[]{0,.44f,1},Shader.TileMode.CLAMP));c.drawCircle(x,y,r,p);c.restore();p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.5f);p.setColor(0x705bdbed);c.drawCircle(x,y,r,p);earth=b;return b;
 }
 private static final class Space extends Drawable{final boolean hero;final Paint paint=new Paint(3);final RectF planet=new RectF();final Path corner=new Path();float[] stars;Shader sky;int w,h;Space(boolean value){hero=value;globe();}protected void onBoundsChange(Rect b){w=b.width();h=b.height();Random rnd=new Random(7317);stars=new float[96];for(int i=0;i<stars.length;i+=2){stars[i]=rnd.nextFloat()*w;stars[i+1]=rnd.nextFloat()*h;}sky=new LinearGradient(0,0,Math.max(1,w),Math.max(1,h),hero?new int[]{0xff102c46,0xff07182b}:new int[]{0xff071426,0xff050c1a},null,Shader.TileMode.CLAMP);float size=Math.min(w*(hero?.73f:.80f),hero?h*.95f:w*.8f);float left=w-size*.71f,top=hero?-size*.14f:h*.02f;planet.set(left,top,left+size,top+size);corner.reset();corner.addRoundRect(new RectF(b),w*.05f,w*.05f,Path.Direction.CW);}
  public void draw(Canvas c){if(hero){c.save();c.clipPath(corner);}paint.setShader(sky);c.drawRect(getBounds(),paint);paint.setShader(null);paint.setColor(0x787ab7ce);paint.setStrokeWidth(hero?1.7f:1.2f);if(stars!=null)c.drawPoints(stars,paint);paint.setAlpha(hero?155:70);c.drawBitmap(earth,null,planet,paint);paint.setAlpha(255);if(hero)c.restore();}
  public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return hero?PixelFormat.TRANSLUCENT:PixelFormat.OPAQUE;}
 }
 private static GradientDrawable rounded(int color,float density){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(22*density);d.setStroke(Math.max(1,(int)density),0xff24465f);return d;}
 private static Drawable button(float d,boolean enter){StateListDrawable state=new StateListDrawable();GradientDrawable enabled=enter?new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff138fa4,0xff23c6b2}):rounded(0xff1b304b,d);enabled.setCornerRadius(20*d);state.addState(new int[]{-android.R.attr.state_enabled},rounded(0xff17283d,d));state.addState(new int[]{android.R.attr.state_pressed},rounded(enter?0xff41d9c4:0xff294b69,d));state.addState(new int[]{},enabled);return state;}
 private static void walk(View v,float d,View[] hero,int depth){if(v instanceof Button){Button b=(Button)v;boolean enter="Enter Game".equalsIgnoreCase(b.getText().toString().trim());b.setBackground(button(d,enter));b.setTextColor(new ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{0xff71869d,0xfff3fbff}));b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setAllCaps(false);}else if(v instanceof TextView){TextView t=(TextView)v;if("73efootball".contentEquals(t.getText())&&t.getParent()instanceof View)hero[0]=(View)t.getParent();t.setTextColor(t.getTextSize()/t.getResources().getDisplayMetrics().scaledDensity<=13?0xff8eafc7:0xffdeedf8);}
  if(v instanceof ViewGroup){if(v.getBackground()instanceof GradientDrawable)v.setBackground(rounded(0xff101f35,d));else if(depth<3&&v.getBackground()instanceof ColorDrawable)v.setBackgroundColor(Color.TRANSPARENT);ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)walk(g.getChildAt(i),d,hero,depth+1);}
 }
 public static void apply(Activity a){ViewGroup content=(ViewGroup)a.findViewById(android.R.id.content);if(content==null||content.getChildCount()==0)return;TransferEditor.attach(a,content);View root=content.getChildAt(0);float d=a.getResources().getDisplayMetrics().density;View[] hero=new View[1];walk(root,d,hero,0);root.setBackground(new Space(false));if(hero[0]!=null){hero[0].setBackground(new Space(true));RuntimeDiagnostics.attach(a,hero[0]);}}
}
